// config/secrets.js
const crypto = require('crypto');

class SecretManager {
  constructor() {
    this.validateSecrets();
  }

  validateSecrets() {
    const requiredSecrets = [
      'JWT_SECRET',
      'DATABASE_URL'
    ];

    const missingSecrets = requiredSecrets.filter(secret => !process.env[secret]);

    if (missingSecrets.length > 0) {
      throw new Error(`Missing required secrets: ${missingSecrets.join(', ')}`);
    }
  }

  get(secretName) {
    const value = process.env[secretName];
    if (!value) {
      throw new Error(`Secret ${secretName} not found`);
    }
    return value;
  }

  // Optional: Runtime secret validation
  validateJwtSecret() {
    const secret = this.get('JWT_SECRET');
    if (secret.length < 32) {
      throw new Error('JWT_SECRET must be at least 32 characters');
    }
  }
}

module.exports = new SecretManager();
```

**Option B: For Production (AWS Secrets Manager / HashiCorp Vault)**
```javascript
// config/secrets-aws.js
const AWS = require('aws-sdk');

class AWSSecretManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
  }

  async getSecret(secretName, useCache = true) {
    if (useCache && this.cache.has(secretName)) {
      return this.cache.get(secretName);
    }

    try {
      const data = await this.client.getSecretValue({ SecretId: secretName }).promise();

      let secret;
      if ('SecretString' in data) {
        secret = data.SecretString;
      } else {
        const buff = Buffer.from(data.SecretBinary, 'base64');
        secret = buff.toString('ascii');
      }

      this.cache.set(secretName, secret);
      return secret;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw error;
    }
  }

  async refreshSecret(secretName) {
    this.cache.delete(secretName);
    return await this.getSecret(secretName, false);
  }
}

module.exports = new AWSSecretManager();
```

