```javascript
// config/index.js
const fs = require('fs');
const path = require('path');

class Config {
  constructor() {
    this.loadEnvironment();
    this.validate();
    this.setDefaults();
  }

  loadEnvironment() {
    // Determine environment
    this.NODE_ENV = process.env.NODE_ENV || 'development';

    // Load appropriate .env file
    const envFile = `.env.${this.NODE_ENV}`;
    if (fs.existsSync(path.join(__dirname, '..', envFile))) {
      require('dotenv').config({ path: envFile });
    } else {
      require('dotenv').config(); // Load .env
    }
  }

  validate() {
    const validationRules = {
      JWT_SECRET: {
        required: true,
        minLength: 32,
        message: 'JWT_SECRET must be at least 32 characters'
      },
      DATABASE_URL: {
        required: this.NODE_ENV === 'production',
        pattern: /^postgres:\/\//,
        message: 'DATABASE_URL must be a valid PostgreSQL connection string'
      },
      PORT: {
        required: false,
        pattern: /^\d+$/,
        message: 'PORT must be a number'
      }
    };

    Object.entries(validationRules).forEach(([key, rule]) => {
      const value = process.env[key];

      if (rule.required && !value) {
        throw new Error(`Missing required configuration: ${key}`);
      }

      if (value && rule.pattern && !rule.pattern.test(value)) {
        throw new Error(`Invalid configuration for ${key}: ${rule.message}`);
      }

      if (value && rule.minLength && value.length < rule.minLength) {
        throw new Error(`Configuration ${key} ${rule.message}`);
      }
    });
  }

  setDefaults() {
    this.PORT = process.env.PORT || 3000;
    this.NODE_ENV = process.env.NODE_ENV || 'development';
    this.JWT_SECRET = process.env.JWT_SECRET;
    this.DATABASE_URL = process.env.DATABASE_URL;
    this.isProduction = this.NODE_ENV === 'production';
    this.isDevelopment = this.NODE_ENV === 'development';
    this.isTest = this.NODE_ENV === 'test';
  }

  get(key) {
    return process.env[key];
  }

  // Mask secrets in logs
  getMaskedConfig() {
    const config = { ...process.env };
    const secretKeys = Object.keys(config).filter(key => 
      key.toLowerCase().includes('secret') || 
      key.toLowerCase().includes('key') || 
      key.toLowerCase().includes('password') ||
      key.toLowerCase().includes('token')
    );

    secretKeys.forEach(key => {
      if (config[key]) {
        config[key] = '***MASKED***';
      }
    });

    return config;
  }
}

module.exports = new Config();
```

