// Implement dependency integrity verification
const crypto = require('crypto');
const fs = require('fs');

function verifyDependencyIntegrity() {
  const packageLock = JSON.parse(fs.readFileSync('package-lock.json', 'utf8'));
  const issues = [];

  Object.entries(packageLock.packages).forEach(([name, pkg]) => {
    if (pkg.integrity) {
      const [algorithm, hash] = pkg.integrity.split('-');
      const fileBuffer = fs.readFileSync(`node_modules/${name}/package.json`);
      const fileHash = crypto.createHash(algorithm).update(fileBuffer).digest('base64');

      if (fileHash !== hash) {
        issues.push(`Integrity check failed for ${name}`);
      }
    }
  });

  if (issues.length > 0) {
    console.error('Dependency integrity issues:', issues);
    if (process.env.NODE_ENV === 'production') {
      process.exit(1);
    }
  }
}

