  // Check for common attack patterns
  const attackPatterns = [
    /<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, // XSS
    /SELECT.*FROM|INSERT.*INTO|UPDATE.*SET|DELETE.*FROM/gi, // Basic SQLi
