    if (typeof value === 'string') {
      for (const pattern of attackPatterns) {
        if (pattern.test(value)) {
          logger.warn(`Potential attack detected: ${pattern} in ${value.substring(0, 50)}`);
          return false;
        }
      }
    }
    return true;
  };

  // Check query parameters
