// Security alerting system
class SecurityAlert {
  constructor() {
    this.alerts = [];
    this.thresholds = {
      failedLogins: 5, // Alert after 5 failed logins
      suspiciousRequests: 10, // Alert after 10 suspicious requests
      rateLimitExceeded: 3 // Alert after 3 rate limit violations
    };

    this.counters = {
      failedLogins: {},
      suspiciousRequests: {},
      rateLimitExceeded: {}
    };
  }

  checkAndAlert(type, identifier, details = {}) {
    if (!this.counters[type]) {
      this.counters[type] = {};
    }

    if (!this.counters[type][identifier]) {
      this.counters[type][identifier] = 0;
    }

    this.counters[type][identifier]++;

    if (this.counters[type][identifier] >= this.thresholds[type]) {
      this.triggerAlert(type, identifier, details);
      return true;
    }

    return false;
  }

  triggerAlert(type, identifier, details) {
    const alert = {
      timestamp: new Date().toISOString(),
      type: `${type.toUpperCase()}_ALERT`,
      identifier,
      count: this.counters[type][identifier],
      details,
      severity: this.getSeverity(type)
    };

    this.alerts.push(alert);

    // Log the alert
    securityLogger.error(alert);

    // TODO: Integrate with external alerting systems
    // - Send email/SMS
    // - Post to Slack/Teams
    // - Trigger PagerDuty
    console.error(`SECURITY ALERT: ${JSON.stringify(alert, null, 2)}`);

    return alert;
  }

  getSeverity(type) {
    const severityMap = {
      failedLogins: 'HIGH',
      suspiciousRequests: 'MEDIUM',
      rateLimitExceeded: 'LOW'
    };

    return severityMap[type] || 'MEDIUM';
  }
}

const securityAlert = new SecurityAlert();

// Apply security alerting to authentication
app.post('/login', (req, res, next) => {
