      reference: `ERR-${Date.now()}` // Reference for support tickets
    });
  }
});

// API version endpoint
app.get('/api/version', (req, res) => {
  res.json({
    version: '1.0.0',
    secure: true,
    timestamp: new Date().toISOString()
  });
});

// ========== ERROR HANDLING ==========

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
