// Example: Secure secrets management
const express = require('express');
const app = express();

// SECURE SECRETS LOADING PATTERNS

// Pattern 1: Using AWS Secrets Manager (Recommended for production)
class SecretsManagerExample {
  constructor() {
    // Never hardcode secrets
    this.secrets = new Map();
  }

  async initializeSecrets() {
    try {
      // Option A: AWS Secrets Manager
      // const { SecretsManager } = require('@aws-sdk/client-secrets-manager');
      // const secretsManager = new SecretsManager();
      // const secret = await secretsManager.getSecretValue({ SecretId: 'app-secrets' });
      // this.secrets.set('DATABASE_URL', secret.DATABASE_URL);

      // Option B: Environment variables with validation
      this.loadFromEnv();

      // Option C: HashiCorp Vault
      // this.loadFromVault();
    } catch (error) {
      console.error('Failed to load secrets:', error);
      process.exit(1);
    }
  }

  loadFromEnv() {
    // Validate required environment variables
    const requiredSecrets = [
      'DATABASE_URL',
      'JWT_SECRET',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY'
    ];

    const missingSecrets = requiredSecrets.filter(secret => !process.env[secret]);

    if (missingSecrets.length > 0) {
      throw new Error(`Missing required secrets: ${missingSecrets.join(', ')}`);
    }

    // Load validated secrets into memory
    requiredSecrets.forEach(secret => {
      this.secrets.set(secret, process.env[secret]);
    });

    // Sanitize for logging (never log full secrets)
    const sanitizedSecrets = new Map();
    this.secrets.forEach((value, key) => {
      sanitizedSecrets.set(key, this.sanitizeForLogging(value, key));
    });
    console.log('Secrets loaded:', Object.fromEntries(sanitizedSecrets));
  }

  sanitizeForLogging(value, key) {
    // Never log full secret values
    if (key.includes('SECRET') || key.includes('KEY') || key.includes('TOKEN')) {
      if (value.length > 8) {
        return `${value.substring(0, 4)}...${value.substring(value.length - 4)}`;
      }
      return '[REDACTED]';
    }
    return value;
  }

  getSecret(key) {
    const value = this.secrets.get(key);
    if (!value) {
      throw new Error(`Secret ${key} not found`);
    }
    return value;
  }
}

// Pattern 2: Environment variable best practices
class EnvironmentConfig {
  static validateEnvironment() {
    const env = process.env.NODE_ENV || 'development';

    // Different validation for different environments
    const configs = {
      development: {
        required: ['DATABASE_URL', 'JWT_SECRET'],
        optional: ['DEBUG', 'LOG_LEVEL']
      },
      test: {
        required: ['DATABASE_URL', 'JWT_SECRET'],
        optional: []
      },
      production: {
        required: [
          'DATABASE_URL',
          'JWT_SECRET',
          'SESSION_SECRET',
          'ENCRYPTION_KEY'
        ],
        optional: ['SENTRY_DSN', 'NEW_RELIC_LICENSE_KEY']
      }
    };

    const config = configs[env] || configs.production;
    const missing = config.required.filter(key => !process.env[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required environment variables for ${env}: ${missing.join(', ')}`);
    }

    console.log(`Environment: ${env}, required config validated`);
    return true;
  }

  static getConfig() {
    return {
      // Application config
      nodeEnv: process.env.NODE_ENV || 'development',
      port: parseInt(process.env.PORT || '3000', 10),

      // Secrets (loaded via getter to avoid exposing in logs)
      get databaseUrl() {
        return process.env.DATABASE_URL;
      },

      get jwtSecret() {
        return process.env.JWT_SECRET;
      },

      // Feature flags
      isProduction: process.env.NODE_ENV === 'production',
      isDevelopment: process.env.NODE_ENV === 'development',
      isTest: process.env.NODE_ENV === 'test'
    };
  }
}

// Pattern 3: Using a secrets loader with rotation support
class SecureSecretsLoader {
  constructor() {
    this.secrets = {};
    this.lastRotation = new Date();
  }

  async loadSecrets() {
    // Choose appropriate loader based on environment
    if (process.env.NODE_ENV === 'production') {
      await this.loadFromSecretsManager();
    } else if (process.env.NODE_ENV === 'development') {
      await this.loadFromEnvFile();
    } else {
      await this.loadFromEnv();
    }
  }

  async loadFromEnvFile() {
    // Only in development, using dotenv
    const dotenv = await import('dotenv');
    const result = dotenv.config();

    if (result.error) {
      console.warn('Warning: Could not load .env file');
    }

    this.loadFromEnv();
  }

  async loadFromEnv() {
    // Basic validation
    const required = this.getRequiredSecrets();
    for (const secret of required) {
      if (!process.env[secret]) {
        throw new Error(`Missing secret: ${secret}`);
      }
      this.secrets[secret] = process.env[secret];
    }
  }

  getRequiredSecrets() {
    const base = ['DATABASE_URL', 'JWT_SECRET'];

    if (process.env.NODE_ENV === 'production') {
      return [...base, 'ENCRYPTION_KEY', 'SESSION_SECRET'];
    }

    return base;
  }

  async rotateSecrets() {
    // Implement secret rotation logic
    console.log('Initiating secret rotation...');
    // This would connect to secrets manager and get updated values
    // Update this.secrets with new values
    this.lastRotation = new Date();
  }

  shouldRotate() {
    // Rotate if secrets are older than 24 hours
    const hoursSinceRotation = (new Date() - this.lastRotation) / (1000 * 60 * 60);
    return hoursSinceRotation > 24;
  }
}

// Usage example in Express app
async function initializeApp() {
  try {
    // Validate environment first
    EnvironmentConfig.validateEnvironment();

    // Load secrets securely
    const secretsManager = new SecretsManagerExample();
    await secretsManager.initializeSecrets();

    // Or use config loader with rotation
    const secretsLoader = new SecureSecretsLoader();
    await secretsLoader.loadSecrets();

    // Set up scheduled rotation in production
    if (process.env.NODE_ENV === 'production') {
      setInterval(async () => {
        if (secretsLoader.shouldRotate()) {
          await secretsLoader.rotateSecrets();
        }
      }, 3600000); // Check every hour
    }

    const config = EnvironmentConfig.getConfig();

    // Application setup using config
    app.listen(config.port, () => {
      console.log(`Server running in ${config.nodeEnv} mode on port ${config.port}`);
      console.log('Secrets securely loaded and validated');
    });

  } catch (error) {
    console.error('Failed to initialize application:', error.message);
    process.exit(1);
  }
}

// Start application
initializeApp().catch(console.error);

module.exports = { app, SecretsManagerExample, EnvironmentConfig, SecureSecretsLoader };

