});

module.exports = app;

// Security Improvement: Add Input Validation
const express = require('express');
const { body, query, param, validationResult } = require('express-validator');
const app = express();

// Add body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const validateInput = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      errors: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
        value: err.value
      }))
    });
  }
  next();
};

// Example route with input validation
app.get('/users/:id',
  [
    param('id')
      .isInt({ min: 1 }).withMessage('User ID must be a positive integer')
      .toInt()
  ],
  validateInput,
  (req, res) => {
    // Safe to use req.params.id here

    // Simulated database query - always use parameterized queries in real apps
    const userId = req.params.id;

    // Return mock data
    res.json({ 
      id: userId, 
      name: 'User ' + userId,
      email: `user${userId}@example.com`
    });
  }
);

// Search endpoint with validation
app.get('/search',
  [
    query('q')
      .trim()
      .escape() // Escapes HTML special characters
      .isLength({ max: 100 }).withMessage('Search query too long')
      .matches(/^[a-zA-Z0-9\s\-_]+$/).withMessage('Invalid characters in search query')
  ],
  validateInput,
  (req, res) => {
    const searchTerm = req.query.q;
    // Safe to use searchTerm here
    res.json({ 
      results: [],
      search: searchTerm 
    });
  }
);

// Existing routes
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Add sanitization middleware for all requests
app.use((req, res, next) => {
  // Sanitize all string inputs
  const sanitize = (obj) => {
    if (typeof obj === 'string') {
      // Remove potentially dangerous characters
      return obj.replace(/[<>"'`]/g, '');
    }
    return obj;
  };

  if (req.body) {
    Object.keys(req.body).forEach(key => {
      req.body[key] = sanitize(req.body[key]);
    });
  }

  if (req.query) {
    Object.keys(req.query).forEach(key => {
      req.query[key] = sanitize(req.query[key]);
    });
  }

  next();
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

// Security Improvement: Add Rate Limiting and Authentication
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
require('dotenv').config(); // Load environment variables

const app = express();

// Security headers
app.use(helmet());

// Rate limiting for different endpoints
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // limit auth endpoints to 5 attempts
  message: 'Too many authentication attempts, please try again later.',
});

// Apply rate limiting
app.use(generalLimiter); // Apply to all routes
app.use('/auth/*', authLimiter); // Stricter limits for auth routes

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));

// Mock user database (in real app, use proper database)
const users = [
  {
    id: 1,
    username: 'alice',
    // In real app, store hashed passwords
    passwordHash: '$2b$10$abc123...', // bcrypt hash of 'password123'
    role: 'user'
  },
  {
    id: 2,
    username: 'admin',
    passwordHash: '$2b$10$xyz789...', // bcrypt hash of 'admin123'
    role: 'admin'
  }
];

// Authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET || 'default-secret-key-change-me', (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Authorization middleware
const authorizeRole = (role) => {
  return (req, res, next) => {
    if (req.user.role !== role) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};

// Authentication endpoints
app.post('/auth/login', async (req, res) => {
  const { username, password } = req.body;

  // Input validation
  if (!username || !password) {
    return res.status(400).json({ error: 'Username and password required' });
  }

  // Find user (in real app, query database)
  const user = users.find(u => u.username === username);

  if (!user) {
    // Use same error message to prevent username enumeration
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // Verify password (in real app, use bcrypt.compare)
  // For demo purposes only - in production, use actual bcrypt comparison
  const isValid = password === 'password123'; // Simplified for demo

  if (!isValid) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // Create JWT token
  const token = jwt.sign(
    { 
      userId: user.id, 
      username: user.username,
      role: user.role 
    },
    process.env.JWT_SECRET || 'default-secret-key-change-me',
    { expiresIn: '1h' } // Token expires in 1 hour
  );

  res.json({ 
    token,
    user: {
      id: user.id,
      username: user.username,
      role: user.role
    }
  });
});

// Protected routes
app.get('/api/users', authenticateToken, (req, res) => {
  // Only return non-sensitive user data
  res.json(users.map(user => ({
    id: user.id,
    username: user.username,
    role: user.role
  })));
});

app.get('/api/admin/users', authenticateToken, authorizeRole('admin'), (req, res) => {
  // Admin-only endpoint
  res.json(users);
});

// Public endpoints
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Don't leak error details in production
  const isProduction = process.env.NODE_ENV === 'production';
  res.status(500).json({
    error: isProduction ? 'Internal server error' : err.message,
    ...(isProduction ? {} : { stack: err.stack })
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

// Secure Express.js Application
// Comprehensive security implementation addressing OWASP Top 10 vulnerabilities

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
const cors = require('cors');
const compression = require('compression');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const hpp = require('hpp');
const csurf = require('csurf');
require('dotenv').config();

const app = express();
const PORT = process.env.PORT || 3000;

// =======================
// SECURITY CONFIGURATION
// =======================

// 1. Security Headers (A05:2021-Security Misconfiguration)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. CORS Configuration (A01:2021-Broken Access Control)
const corsOptions = {
  origin: process.env.CORS_ORIGIN 
    ? process.env.CORS_ORIGIN.split(',') 
    : ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200
};
app.use(cors(corsOptions));

// 3. Rate Limiting (A04:2021-Insecure Design)
const generalLimiter = rateLimit({
  windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000,
  max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100,
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
  skipSuccessfulRequests: false,
  keyGenerator: (req) => {
    return req.ip || req.connection.remoteAddress;
  }
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: {
    error: 'Too many authentication attempts, please try again in 15 minutes.'
  }
});

app.use('/auth/*', authLimiter);
app.use(generalLimiter);

// 4. Body Parsing with Limits
app.use(express.json({
  limit: process.env.MAX_BODY_SIZE || '10kb',
  verify: (req, res, buf) => {
    // Check for JSON parsing errors
    try {
      JSON.parse(buf.toString());
    } catch (e) {
      throw new Error('Invalid JSON');
    }
  }
}));

app.use(express.urlencoded({
  extended: true,
  limit: process.env.MAX_BODY_SIZE || '10kb'
}));

// 5. Compression
app.use(compression());

// 6. Data Sanitization (A03:2021-Injection)
// Sanitize data against NoSQL query injection
app.use(mongoSanitize({
  replaceWith: '_',
  onSanitize: ({ req, key }) => {
    console.warn(`Attempted NoSQL injection detected: ${key}`);
  }
}));

// Sanitize data against XSS
app.use(xss());

// Protect against HTTP Parameter Pollution
app.use(hpp());

// 7. CSRF Protection (A01:2021-Broken Access Control)
// Note: For API-only applications, CSRF might not be needed
// app.use(csurf({ cookie: true }));

// =======================
// CUSTOM MIDDLEWARE
// =======================

// Input validation middleware
const validateInput = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Don't expose too much information
    const errorMessages = errors.array().map(err => ({
      field: err.param,
      message: 'Invalid input'
    }));

    return res.status(400).json({ 
      error: 'Validation failed',
      details: errorMessages
    });
  }
  next();
};

// Authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.startsWith('Bearer ') 
    ? authHeader.slice(7) 
    : null;

  if (!token) {
    return res.status(401).json({ 
      error: 'Authentication required',
      code: 'AUTH_REQUIRED'
    });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    // Don't leak specific error information
    return res.status(403).json({ 
      error: 'Invalid or expired token',
      code: 'INVALID_TOKEN'
    });
  }
};

// Authorization middleware
const authorizeRole = (...allowedRoles) => {
  return (req, res, next) => {
    if (!req.user || !allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ 
        error: 'Insufficient permissions',
        code: 'FORBIDDEN'
      });
    }
    next();
  };
};

// Request logging middleware
app.use((req, res, next) => {
  const start = Date.now();
  const requestId = Math.random().toString(36).substring(7);

  // Log request (sanitized)
  console.log(`[${new Date().toISOString()}] [${requestId}] ${req.method} ${req.path}`);

  // Add request ID to response
  res.setHeader('X-Request-ID', requestId);

  // Log response
