class SecureCredentialRotator {
  constructor() {
    this.client = new SecretsManagerClient({ region: 'us-east-1' });
    this.rotationLog = [];
  }

  async rotateCredential(secretName, newValueGenerator) {
    try {
      // 1. Generate new credential (DO NOT LOG IT)
      const newValue = await newValueGenerator();

      // 2. Update in secure storage (AWS Secrets Manager example)
      const command = new UpdateSecretCommand({
        SecretId: secretName,
