// Secure Express.js Application with Common Security Fixes

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const xss = require('xss-clean');
const hpp = require('hpp');
const mongoSanitize = require('express-mongo-sanitize');
const expressValidator = require('express-validator');
const compression = require('compression');

const app = express();

// ====================
// 1. SECURITY MIDDLEWARE
// ====================

// Security headers with Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Enable CORS with safe defaults
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Data sanitization
app.use(xss()); // Prevent XSS attacks
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent HTTP Parameter Pollution

// Compression
app.use(compression());

// ====================
// 2. AUTHENTICATION MIDDLEWARE
// ====================

// Basic authentication middleware example
const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Authentication token required'
    });
  }

  const token = authHeader.split(' ')[1];

  // In production, use JWT verification or similar
  // This is a simplified example
  try {
    // Verify token (example using a hypothetical auth service)
    // const decoded = verifyToken(token);
    // req.user = decoded;
    next();
  } catch (error) {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Invalid authentication token'
    });
  }
};

// Role-based authorization middleware
const authorize = (...roles) => {
  return (req, res, next) => {
    if (!req.user || !roles.includes(req.user.role)) {
      return res.status(403).json({
        error: 'Forbidden',
        message: 'You do not have permission to access this resource'
      });
    }
    next();
  };
};

// ====================
// 3. INPUT VALIDATION MIDDLEWARE
// ====================

const { body, query, param, validationResult } = require('express-validator');

const validate = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));

    const errors = validationResult(req);
    if (errors.isEmpty()) {
      return next();
    }

    return res.status(400).json({
      error: 'Validation Error',
      details: errors.array()
    });
  };
};

// ====================
// 4. SECURE ROUTES
// ====================

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.APP_VERSION || '1.0.0'
  });
});

// Protected user endpoint with validation
app.get('/api/users', 
  authenticate,
  [
    query('page').optional().isInt({ min: 1 }).toInt(),
    query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    query('sortBy').optional().isIn(['name', 'email', 'createdAt']),
    query('order').optional().isIn(['asc', 'desc'])
  ],
  validate,
  (req, res) => {
    const { page = 1, limit = 10, sortBy = 'name', order = 'asc' } = req.query;

    // Example user data (in production, this would come from a database)
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        role: 'user',
        createdAt: '2024-01-01T00:00:00Z'
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        role: 'admin',
        createdAt: '2024-01-02T00:00:00Z'
      },
    ];

    // Filter sensitive information
    const safeUsers = users.map(user => ({
      id: user.id,
      name: user.name,
      role: user.role
    }));

    res.json({
      data: safeUsers,
      pagination: {
        page: parseInt(page),
        limit: parseInt(limit),
        total: users.length
      }
    });
  }
);

// Get user by ID with input validation
app.get('/api/users/:id',
  authenticate,
  [
    param('id').isInt({ min: 1 }).withMessage('User ID must be a positive integer')
  ],
  validate,
  (req, res) => {
    const { id } = req.params;

    // In production, fetch from database with proper sanitization
    const user = {
      id: parseInt(id),
      name: 'Test User',
      email: 'test@example.com',
      role: 'user'
    };

    res.json({
      id: user.id,
      name: user.name,
      role: user.role
    });
  }
);

// ====================
// 5. ERROR HANDLING
// ====================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error(err.stack); // Log error for debugging

  // Don't leak stack traces in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    message: isProduction ? 'Something went wrong' : err.message,
    ...(isProduction ? {} : { stack: err.stack })
  });
});

// ====================
// 6. SERVER CONFIGURATION
// ====================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Starting graceful shutdown...');
  // Close database connections, cleanup, etc.
  process.exit(0);
});

app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

