# Security Guidelines for Express.js Applications

## Summary of Security Issues Found in Original app.js

### **Critical Issues (Must Fix Immediately)**

1. **No Security Headers** - Missing CSP, HSTS, XSS protection
2. **No Authentication/Authorization** - Anyone can access all endpoints
3. **No Input Validation** - Vulnerable to injection attacks
4. **No Rate Limiting** - Vulnerable to brute force attacks
5. **Error Information Disclosure** - Stack traces exposed
6. **Hardcoded Secrets** - Sensitive data in `.env.test`
7. **Missing CORS Configuration** - Open to cross-site requests
8. **No Session Management** - No secure session handling

## **Detailed Security Recommendations**

### **1. Injection Prevention**

#### **SQL/NoSQL Injection**
```javascript
// ❌ UNSAFE - Original code has no database operations
// But if added, this would be vulnerable:

app.get('/users/:id', (req, res) => {
  const userId = req.params.id;
  // VULNERABLE: Direct concatenation
  db.query(`SELECT * FROM users WHERE id = ${userId}`);
});

// ✅ SECURE - Use parameterized queries
app.get('/users/:id', [
  param('id').isInt().withMessage('User ID must be an integer')
], async (req, res) => {
  const userId = req.params.id;
  // SAFE: Parameterized query
  const user = await db.query(
    'SELECT * FROM users WHERE id = $1',
    [userId]
  );
});
```

#### **XSS Prevention**
```javascript
// ❌ UNSAFE - No output encoding
res.send(`<div>${userInput}</div>`);

// ✅ SECURE - Use template engines with auto-escaping
res.render('profile', { username: userInput }); // Auto-escaped

// ✅ SECURE - Use xss-clean middleware
app.use(xss());
```

### **2. Authentication & Authorization**

#### **Missing Authentication**
```javascript
// ❌ UNSAFE - No authentication
app.get('/admin', (req, res) => {
  res.json({ data: 'sensitive admin data' });
});

// ✅ SECURE - JWT-based authentication
const jwt = require('jsonwebtoken');

// Authentication middleware
const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    return res.status(401).json({ error: 'Invalid token' });
  }
};

// Role-based authorization
const authorize = (...roles) => {
  return (req, res, next) => {
    if (!req.user || !roles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Access denied' });
    }
    next();
  };
};

// Protected route
app.get('/admin', authenticate, authorize('admin'), (req, res) => {
  res.json({ data: 'sensitive admin data' });
});
```

### **3. Input Validation**

#### **Missing Validation**
```javascript
// ❌ UNSAFE - No input validation
app.post('/users', (req, res) => {
  const { email, password } = req.body;
  // Directly use user input without validation
});

// ✅ SECURE - Comprehensive validation
const { body, validationResult } = require('express-validator');

app.post('/users', [
  // Email validation
  body('email')
    .isEmail()
    .normalizeEmail()
    .withMessage('Valid email is required'),

  // Strong password validation
  body('password')
    .isStrongPassword({
      minLength: 12,
      minLowercase: 1,
      minUppercase: 1,
      minNumbers: 1,
      minSymbols: 1
    })
    .withMessage('Password must be at least 12 characters with uppercase, lowercase, number, and symbol'),

  // Sanitize input
  body('name')
    .trim()
    .escape()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be 1-100 characters')
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Safe to use validated input
  const { email, password, name } = req.body;
});
```

### **4. Security Headers & Middleware**

#### **Missing Security Headers**
```javascript
// ❌ UNSAFE - Original: No security headers
const app = express();

// ✅ SECURE - Comprehensive security middleware
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

// Security headers with Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"], // Minimize use of unsafe-inline
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// CORS with safe defaults
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE']
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests
  message: 'Too many requests from this IP'
});
app.use('/api/', limiter);
```

### **5. Session Management**

#### **No Session Security**
```javascript
// ✅ SECURE - Session configuration
const session = require('express-session');
const RedisStore = require('connect-redis')(session);
const redis = require('redis');

const redisClient = redis.createClient({
  url: process.env.REDIS_URL,
  password: process.env.REDIS_PASSWORD,
  tls: process.env.NODE_ENV === 'production'
});

app.use(session({
  store: new RedisStore({ client: redisClient }),
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  name: 'sessionId',
  cookie: {
    secure: process.env.NODE_ENV === 'production', // HTTPS only in production
    httpOnly: true, // Prevent JavaScript access
    sameSite: 'strict', // CSRF protection
    maxAge: 24 * 60 * 60 * 1000, // 24 hours
    domain: process.env.COOKIE_DOMAIN
  }
}));
```

### **6. Error Handling**

#### **Information Disclosure**
```javascript
// ❌ UNSAFE - Stack trace exposure
app.use((err, req, res, next) => {
  res.status(500).send(err.stack); // Exposes internal details
});

// ✅ SECURE - Safe error handling
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't expose stack traces in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    message: isProduction ? 'Something went wrong' : err.message,
    requestId: req.id // For tracking
  });
});
```

### **7. File Upload Security**

#### **Missing File Validation**
```javascript
// ✅ SECURE - File upload validation
const multer = require('multer');
const path = require('path');

const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, process.env.UPLOAD_PATH);
  },
  filename: (req, file, cb) => {
    // Create safe filename
    const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
    const ext = path.extname(file.originalname).toLowerCase();
    cb(null, file.fieldname + '-' + uniqueSuffix + ext);
  }
});

const fileFilter = (req, file, cb) => {
  // Allowed MIME types
  const allowedMimeTypes = [
    'image/jpeg',
    'image/png',
    'image/gif',
    'application/pdf'
  ];

  // Check file extension
  const ext = path.extname(file.originalname).toLowerCase();
  const allowedExts = ['.jpg', '.jpeg', '.png', '.gif', '.pdf'];

  if (allowedMimeTypes.includes(file.mimetype) && allowedExts.includes(ext)) {
    cb(null, true);
  } else {
    cb(new Error('Invalid file type'), false);
  }
};

const upload = multer({
  storage: storage,
  fileFilter: fileFilter,
  limits: {
    fileSize: 5 * 1024 * 1024, // 5MB max
    files: 5 // Max number of files
  }
});

app.post('/upload', upload.array('files', 5), (req, res) => {
  // Process uploaded files
});
```

### **8. Dependency Security**

#### **Missing Dependency Management**
```bash
# ❌ UNSAFE - No dependency checking

# ✅ SECURE - Regular security checks
# Install security tools
npm install --save-dev npm-audit npm-check-updates

# Check for vulnerabilities
npm audit

# Check for outdated packages
npx npm-check-updates

# Run security check script in package.json
{
  "scripts": {
    "security-check": "npm audit && npx npm-check-updates",
    "audit-fix": "npm audit fix"
  }
}
```

