// Security Test Examples
// Demonstrates vulnerable patterns to watch for

// ====================
// INJECTION VULNERABILITIES
// ====================

// 1. SQL Injection
function vulnerableSQL(userId) {
  // ❌ VULNERABLE: Direct string concatenation
  const query = `SELECT * FROM users WHERE id = ${userId}`;
  // Direct user input in SQL query

  const maliciousInput = "1; DROP TABLE users; --";
  // Result: SELECT * FROM users WHERE id = 1; DROP TABLE users; --

  return query;
}

function safeSQL(userId) {
  // ✅ SAFE: Parameterized query
  const query = 'SELECT * FROM users WHERE id = $1';
  const params = [userId];
  // User input is treated as data, not code

  return { query, params };
}

// 2. Command Injection
function vulnerableCommand(filename) {
  // ❌ VULNERABLE: User input in shell command
  const command = `cat ${filename}`;
  // User could input: file.txt; rm -rf /

  return command;
}

function safeCommand(filename) {
  // ✅ SAFE: Validate and sanitize input
  const safeFilename = filename.replace(/[^a-zA-Z0-9._-]/g, '');
  const command = ['cat', safeFilename];
  // Using array syntax prevents shell injection

  return command;
}

// ====================
// XSS VULNERABILITIES
// ====================

function vulnerableXSS(userInput) {
  // ❌ VULNERABLE: Direct output without escaping
  const html = `<div>${userInput}</div>`;
  // User could input: <script>alert('xss')</script>

  return html;
}

function safeXSS(userInput) {
  // ✅ SAFE: Proper escaping
  const escapeHTML = (str) => {
    return str.replace(/[&<>"']/g, (char) => {
      const escapeMap = {
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#39;'
      };
      return escapeMap[char] || char;
    });
  };

  const html = `<div>${escapeHTML(userInput)}</div>`;
  return html;
}

// ====================
// AUTHENTICATION VULNERABILITIES
// ====================

// 3. Weak Password Handling
function vulnerableAuth() {
  // ❌ VULNERABLE: Weak password hashing
  const weakHash = (password) => {
    // MD5 is broken, easily crackable
    return require('crypto').createHash('md5').update(password).digest('hex');
  };

  return { hash: weakHash };
}

function safeAuth() {
  // ✅ SAFE: Strong password hashing
  const bcrypt = require('bcrypt');

  const hashPassword = async (password) => {
    const saltRounds = 12; // OWASP recommendation
    return await bcrypt.hash(password, saltRounds);
  };

  const verifyPassword = async (password, hash) => {
    return await bcrypt.compare(password, hash);
  };

  return { hashPassword, verifyPassword };
}

// ====================
// INSECURE DIRECTIVES
// ====================

function vulnerableConfig() {
  // ❌ VULNERABLE: Insecure configuration
  const config = {
    session: {
      secret: 'hardcoded-secret', // Should be from environment
      cookie: {
        secure: false, // Should be true in production
        httpOnly: false, // Should be true
        sameSite: 'lax' // Should be 'strict'
      }
    },
    cors: {
      origin: '*', // Too permissive
      credentials: true
    }
  };

  return config;
}

function safeConfig() {
  // ✅ SAFE: Secure configuration
  const config = {
    session: {
      secret: process.env.SESSION_SECRET || crypto.randomBytes(32).toString('hex'),
      cookie: {
        secure: process.env.NODE_ENV === 'production',
        httpOnly: true,
        sameSite: 'strict',
        maxAge: 24 * 60 * 60 * 1000
      }
    },
    cors: {
      origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
      credentials: true,
      methods: ['GET', 'POST', 'PUT', 'DELETE']
    }
  };

  return config;
}

// ====================
// FILE UPLOAD VULNERABILITIES
// ====================

function vulnerableUpload() {
  // ❌ VULNERABLE: No file validation
  const multer = require('multer');

  const upload = multer({
    dest: 'uploads/',
    // No file type validation
    // No size limits
    // No filename sanitization
  });

  return upload;
}

function safeUpload() {
  // ✅ SAFE: Comprehensive file validation
  const multer = require('multer');
  const path = require('path');

  const fileFilter = (req, file, cb) => {
    const allowedTypes = [
      'image/jpeg',
      'image/png',
      'image/gif',
      'application/pdf'
    ];

    const allowedExts = ['.jpg', '.jpeg', '.png', '.gif', '.pdf'];
    const ext = path.extname(file.originalname).toLowerCase();

    if (allowedTypes.includes(file.mimetype) && allowedExts.includes(ext)) {
      cb(null, true);
    } else {
      cb(new Error('Invalid file type'), false);
    }
  };

  const storage = multer.diskStorage({
    destination: 'uploads/',
    filename: (req, file, cb) => {
      const uniquePrefix = Date.now() + '-' + Math.round(Math.random() * 1E9);
      const safeName = file.originalname.replace(/[^a-zA-Z0-9._-]/g, '');
      cb(null, uniquePrefix + '-' + safeName);
    }
  });

  const upload = multer({
    storage: storage,
    fileFilter: fileFilter,
    limits: {
      fileSize: 5 * 1024 * 1024, // 5MB
      files: 5
    }
  });

  return upload;
}

// ====================
// LOGGING VULNERABILITIES
// ====================

function vulnerableLogging() {
  // ❌ VULNERABLE: Logging sensitive data
  const logger = {
    info: (data) => {
      console.log('User data:', {
        username: data.username,
        password: data.password, // NEVER log passwords!
        email: data.email,
        creditCard: data.creditCard // NEVER log sensitive data!
      });
    }
  };

  return logger;
}

function safeLogging() {
  // ✅ SAFE: Mask sensitive data in logs
  const maskSensitive = (obj) => {
    const sensitiveFields = ['password', 'token', 'secret', 'creditCard', 'ssn'];
    const masked = { ...obj };

    sensitiveFields.forEach(field => {
      if (masked[field]) {
        masked[field] = '[REDACTED]';
      }
    });

    return masked;
  };

  const logger = {
    info: (data, message) => {
      const safeData = maskSensitive(data);
      console.log(message, safeData);
    },

    security: (event, details) => {
      console.log('SECURITY EVENT:', {
        event,
        timestamp: new Date().toISOString(),
        details: maskSensitive(details),
        ip: details.ip
      });
    }
  };

  return logger;
}

// Export testable functions
